test("artifactGraph runtime foreach materializes and launches generated tasks in one scheduleRun", async () => {
	const cwd = makeProject();
	try {
		writeAgent(cwd, "unit-scout", "read");
		const prompts = captureSubagentPrompts();
		const spec = workflowSpec("unit-scout", {
			artifactGraph: {
				stages: [
					{
						id: "extract",
						type: "single",
						prompt: "Extract",
					},
					{
						id: "verify",
						type: "foreach",
						from: { source: "extract", path: "$.claims" },
						maxConcurrency: 2,
						each: { prompt: "Verify ${item}" },
					},
					{
						id: "summary",
						type: "reduce",
						from: "verify",
						prompt: "Summarize",
					},
				],
			},
		});
		const compiled = await compileWorkflow(spec, { cwd, task: "Check claims" });
		const { run } = await createWorkflowRunRecord(
			cwd,
			compiled,
			join(cwd, "workflows", "unit.json"),
		);
		await writeStaticRunArtifacts(cwd, run, compiled, spec);

		await completeTask(cwd, run.tasks[0], {
			claims: [{ id: "CLAIM_A", text: "A" }, "plain claim"],
		});
		await writeRunRecord(cwd, run);

		await scheduleRun(cwd, run.runId);
		const materialized = await readRunRecord(cwd, run.runId);
		const specIds = materialized.tasks.map((task) => task.specId);
		assert.deepEqual(specIds, [
			"extract.main",
			"verify.claim_a",
			"verify.item-002",
			"summary.main",
		]);
		assert.equal(
			materialized.tasks.find((task) => task.specId === "verify.claim_a")
				?.status,
			"running",
		);
		assert.equal(
			materialized.tasks.find((task) => task.specId === "verify.item-002")
				?.status,
			"running",
		);
		assert.equal(prompts.length, 2);
		assert(prompts.every((prompt) => prompt.includes("Verify")));
		assert.deepEqual(
			materialized.tasks.find((task) => task.specId === "verify.claim_a")
				?.foreachGenerated,
			{ placeholderSpecId: "verify.item" },
		);
		const materializedCompiled = JSON.parse(
			readFileSync(
				join(cwd, ".pi", "workflows", materialized.runId, "compiled.json"),
				"utf8",
			),
		);
		assert.deepEqual(
			materializedCompiled.tasks.find((task) => task.id === "verify.claim_a")
				.foreachGenerated,
			{ placeholderSpecId: "verify.item" },
		);
		assert.deepEqual(
			materializedCompiled.tasks.find((task) => task.id === "summary.main")
				.dependsOn,
			["verify.claim_a", "verify.item-002"],
		);
	} finally {
		setSubagentApiForTests(undefined);
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("streaming foreach waits for unresolved non-source dependencies", () => {
	const compiledFlow = {
		stages: [{ id: "verify", sourcePolicy: "require-success" }],
		tasks: [
			{ id: "review.item", stageId: "review" },
			{ id: "gate.main", stageId: "gate" },
			{ id: "verify.item", stageId: "verify" },
		],
	};
	const compiledTask = {
		specId: "verify.item",
		stageId: "verify",
		dependsOn: ["review.item", "gate.main"],
		foreach: {
			from: {
				stage: "review",
				path: "$.findings",
				streaming: { enabled: true },
			},
		},
	};

	assert.equal(
		dependenciesReady(
			compiledTask,
			new Map([
				["review.item", { status: "completed" }],
				["gate.main", { status: "pending" }],
			]),
			compiledFlow,
		),
		false,
	);
	assert.equal(
		dependenciesReady(
			compiledTask,
			new Map([
				["review.item", { status: "completed" }],
				["gate.main", { status: "completed" }],
			]),
			compiledFlow,
		),
		true,
	);
});

test("streaming foreach appends items before all upstream siblings finish", async () => {
	const cwd = makeProject();
	captureSubagentPrompts();
	try {
		writeAgent(cwd, "unit-scout", "read");
		const spec = workflowSpec("unit-scout", {
			artifactGraph: {
				stages: [
					{ id: "extract", type: "single", prompt: "Extract" },
					{
						id: "review",
						type: "foreach",
						from: { source: "extract", path: "$.claims" },
						output: { partial: { paths: ["$.findings"] } },
						each: { prompt: "Review ${item}" },
					},
					{
						id: "verify",
						type: "foreach",
						from: {
							source: "review",
							path: "$.findings",
							streaming: { enabled: true },
						},
						each: { prompt: "Verify ${item}" },
					},
					{ id: "summary", type: "reduce", from: "verify", prompt: "Sum" },
				],
			},
		});
		const compiled = await compileWorkflow(spec, { cwd, task: "Check claims" });
		const { run } = await createWorkflowRunRecord(
			cwd,
			compiled,
			join(cwd, "workflows", "unit.json"),
		);
		await writeStaticRunArtifacts(cwd, run, compiled, spec);
		await completeTask(cwd, run.tasks[0], { claims: ["a", "b"] });
		await writeRunRecord(cwd, run);

		await scheduleRun(cwd, run.runId);
		let current = await readRunRecord(cwd, run.runId);
		await completeTask(cwd, taskBySpec(current, "review.item-001"), {
			findings: [{ id: "FINDING_A", text: "A" }],
		});
		await writeRunRecord(cwd, current);

		await scheduleRun(cwd, run.runId);
		current = await readRunRecord(cwd, run.runId);
		assert.deepEqual(
			current.tasks.map((task) => task.specId),
			[
				"extract.main",
				"review.item-001",
				"review.item-002",
				"verify.item",
				"verify.finding_a",
				"summary.main",
			],
		);
		assert.equal(taskBySpec(current, "verify.item").status, "pending");
		assert.equal(
			taskBySpec(current, "verify.item").statusDetail,
			"foreach_streaming_waiting",
		);
		assert.deepEqual(taskBySpec(current, "summary.main").dependsOn, [
			"verify.item",
			"verify.finding_a",
		]);
		assert.deepEqual(taskBySpec(current, "verify.finding_a").dependsOn, [
			"review.item-001",
		]);

		await completeTask(cwd, taskBySpec(current, "review.item-002"), {
			findings: [{ id: "FINDING_B", text: "B" }],
		});
		await writeRunRecord(cwd, current);
		await scheduleRun(cwd, run.runId);
		current = await readRunRecord(cwd, run.runId);
		assert.deepEqual(
			current.tasks
				.filter((task) => task.stageId === "verify")
				.map((task) => task.specId),
			["verify.item", "verify.finding_a", "verify.finding_b"],
		);
		assert.equal(taskBySpec(current, "verify.item").status, "completed");
		assert.equal(
			taskBySpec(current, "verify.item").statusDetail,
			"foreach_streaming_complete",
		);
		assert.deepEqual(taskBySpec(current, "summary.main").dependsOn, [
			"verify.item",
			"verify.finding_a",
			"verify.finding_b",
		]);
		assert.deepEqual(taskBySpec(current, "verify.finding_b").dependsOn, [
			"review.item-002",
		]);
	} finally {
		setSubagentApiForTests(undefined);
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

